import java.util.Scanner;

public class LecturaDatos {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);

        // Leer una cadena
        System.out.print("Introduce tu nombre: ");
        String nombre = teclado.nextLine();

        // Leer un entero
        System.out.print("Introduce tu edad: ");
        int edad = teclado.nextInt();

        // Limpiar el buffer despues de nextInt()
        teclado.nextLine();

        // Leer una cadena completa
        System.out.print("Introduce tu ciudad: ");
        String ciudad = teclado.nextLine();

        // Leer un decimal
        System.out.print("Introduce tu nota media: ");
        double nota = teclado.nextDouble();

        // Mostrar los datos
        System.out.println();
        System.out.println("=== FICHA DEL ALUMNO ===");
        System.out.println("Nombre: " + nombre);
        System.out.println("Edad: " + edad + " anios");
        System.out.println("Ciudad: " + ciudad);
        System.out.println("Nota media: " + nota);

        teclado.close();
    }
}

import java.util.Scanner;

public class CalculadoraInteractiva {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);

        System.out.println("=== CALCULADORA INTERACTIVA ===");
        System.out.println();

        // Primer numero
        System.out.print("Introduce el primer numero: ");
        double num1 = teclado.nextDouble();

        // Limpiar buffer
        teclado.nextLine();

        // Segundo numero
        System.out.print("Introduce el segundo numero: ");
        double num2 = teclado.nextDouble();

        // Operacion
        teclado.nextLine(); // limpiar buffer
        System.out.println();
        System.out.println("Operaciones disponibles:");
        System.out.println("  + Suma");
        System.out.println("  - Resta");
        System.out.println("  * Multiplicacion");
        System.out.println("  / Division");
        System.out.print("Introduce el operador: ");
        String operador = teclado.nextLine();

        // Calcular resultado
        System.out.println();
        double resultado = 0;
        boolean operacionValida = true;

        switch (operador) {
            case "+":
                resultado = num1 + num2;
                break;
            case "-":
                resultado = num1 - num2;
                break;
            case "*":
                resultado = num1 * num2;
                break;
            case "/":
                if (num2 != 0) {
                    resultado = num1 / num2;
                } else {
                    System.out.println("Error: No se puede dividir por cero.");
                    operacionValida = false;
                }
                break;
            default:
                System.out.println("Operador no valido.");
                operacionValida = false;
        }

        if (operacionValida) {
            System.out.println(num1 + " " + operador + " " + num2 + " = " + resultado);
        }

        teclado.close();
    }
}

