import java.util.Scanner;

public class CalculadoraIMC {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);

        System.out.print("Introduce tu peso en kg: ");
        double peso = teclado.nextDouble();

        System.out.print("Introduce tu altura en metros: ");
        double altura = teclado.nextDouble();

        double imc = peso / (altura * altura);

        System.out.println();
        System.out.println("Tu IMC es: " + String.format("%.2f", imc));

        if (imc < 18.5) {
            System.out.println("Categoria: Bajo peso");
        } else if (imc < 25.0) {
            System.out.println("Categoria: Peso normal");
        } else if (imc < 30.0) {
            System.out.println("Categoria: Sobrepeso");
        } else {
            System.out.println("Categoria: Obesidad");
        }

        teclado.close();
    }
}

import java.util.Scanner;

public class ConversorDivisas {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);

        final double EURO_A_DOLAR = 1.08;
        final double EURO_A_LIBRA = 0.86;
        final double EURO_A_YEN = 163.5;

        System.out.println("=== CONVERSOR DE DIVISAS ===");
        System.out.print("Introduce la cantidad en euros: ");
        double euros = teclado.nextDouble();

        teclado.nextLine();

        System.out.println();
        System.out.println("Divisas disponibles:");
        System.out.println("1 - Dolares");
        System.out.println("2 - Libras esterlinas");
        System.out.println("3 - Yenes");
        System.out.println("4 - Todas");
        System.out.print("Elige una opcion: ");
        int opcion = teclado.nextInt();

        System.out.println();
        System.out.println(euros + " EUR equivalen a:");

        switch (opcion) {
            case 1:
                System.out.println(String.format("%.2f USD", euros * EURO_A_DOLAR));
                break;
            case 2:
                System.out.println(String.format("%.2f GBP", euros * EURO_A_LIBRA));
                break;
            case 3:
                System.out.println(String.format("%.2f JPY", euros * EURO_A_YEN));
                break;
            case 4:
                System.out.println(String.format("%.2f USD", euros * EURO_A_DOLAR));
                System.out.println(String.format("%.2f GBP", euros * EURO_A_LIBRA));
                System.out.println(String.format("%.2f JPY", euros * EURO_A_YEN));
                break;
            default:
                System.out.println("Opcion no valida.");
        }

        teclado.close();
    }
}

