public class EjemploPrintf {
    public static void main(String[] args) {
        String nombre = "Ana";
        int edad = 20;
        double nota = 8.756;

        // Formato basico
        System.out.printf("Nombre: %s, Edad: %d, Nota: %.1f%n", nombre, edad, nota);

        // Ancho fijo y alineacion
        System.out.printf("%10s | %5d | %6.2f%n", nombre, edad, nota);

        // Relleno con ceros
        System.out.printf("Codigo: %05d%n", 42);

        // Alineacion a la izquierda con -
        System.out.printf("%-10s | %5d | %6.2f%n", nombre, edad, nota);

        // Multiples valores
        System.out.printf("La nota de %s es %.2f y tiene %d anios.%n", nombre, nota, edad);

        // Porcentaje
        double porcentaje = 0.857;
        System.out.printf("Progreso: %.1f%%%n", porcentaje * 100);
    }
}

public class FormateoAvanzado {
    public static void main(String[] args) {
        // String.format() para crear cadenas formateadas
        String nombre = "Carlos";
        double nota = 7.856;
        String mensaje = String.format("%s ha obtenido %.2f puntos", nombre, nota);
        System.out.println(mensaje);

        // Crear una tabla de notas formateada
        System.out.println();
        System.out.printf("%n=== NOTAS DEL ALUMNO ===%n%n");
        System.out.printf("%-20s | %6s | %8s%n", "Asignatura", "Nota", "Estado");
        System.out.printf("%-20s-+-%6s-+-%8s%n", "--------------------", "------", "--------");

        String[] asignaturas = {"Programacion", "Base de Datos", "Ingles", "Sistemas"};
        double[] notas = {8.5, 7.0, 6.75, 9.25};

        for (int i = 0; i < asignaturas.length; i++) {
            String estado = notas[i] >= 5.0 ? "Aprobado" : "Suspendido";
            System.out.printf("%-20s | %6.2f | %8s%n", asignaturas[i], notas[i], estado);
        }

        System.out.println();

        // Formato con relleno de ceros
        System.out.println("Codigos de alumno:");
        for (int i = 1; i <= 5; i++) {
            System.out.printf("  Alumno %03d%n", i);
        }
    }
}

