        }
    }
}

public class ReciboCompra {
    public static void main(String[] args) {
        String[] productos = {"Leche", "Pan", "Huevos", "Manzanas"};
        int[] cantidades = {2, 1, 12, 3};
        double[] precios = {1.20, 0.95, 2.50, 1.80};
        double iva = 0.21;

        System.out.println();
        System.out.println("+---------------------------------------+");
        System.out.println("|          RECIBO DE COMPRA             |");
        System.out.println("+---------------------------------------+");
        System.out.printf("| %-12s | %4s | %6s | %7s |%n", "Producto", "Cant", "P.Uni", "Subtotal");
        System.out.println("+---------------------------------------+");

        double totalSinIva = 0;

        for (int i = 0; i < productos.length; i++) {
            double subtotal = cantidades[i] * precios[i];
            totalSinIva += subtotal;
            System.out.printf("| %-12s | %4d | %6.2f | %7.2f |%n",
                productos[i], cantidades[i], precios[i], subtotal);
        }

        double importeIva = totalSinIva * iva;
        double totalConIva = totalSinIva + importeIva;

        System.out.println("+---------------------------------------+");
        System.out.printf("|                 SUBTOTAL:   %8.2f |%n", totalSinIva);
        System.out.printf("|                 IVA (21%%):   %8.2f |%n", importeIva);
        System.out.printf("|                 TOTAL:      %8.2f |%n", totalConIva);
        System.out.println("+---------------------------------------+");
    }
}

