import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class EjemploBufferedReader {
    public static void main(String[] args) {
        /*
         * BufferedReader es mas eficiente que Scanner para
         * leer grandes volumenes de datos del teclado.
         * Internamente usa un buffer para reducir accesos al SO.
         */
        try {
            BufferedReader lector = new BufferedReader(
                new InputStreamReader(System.in)
            );

            System.out.print("Introduce tu nombre: ");
            String nombre = lector.readLine();

            System.out.print("Introduce tu edad: ");
            int edad = Integer.parseInt(lector.readLine());

            System.out.printf("Hola %s, tienes %d anios.%n", nombre, edad);

            lector.close();

        } catch (IOException e) {
            System.err.println("Error de lectura: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Error: no se pudo convertir a numero.");
        }
    }
}

public class SalidasEstandar {
    public static void main(String[] args) {
        // System.out: salida normal (por defecto, se muestra en color negro)
        System.out.println("Esto es una salida normal.");

        // System.err: salida de errores (en muchos terminales se muestra en rojo)
        System.err.println("Esto es un mensaje de error.");

        // Diferencia en la practica:
        // Ambos van a la consola, pero System.err se puede redirigir
        // independientemente en la linea de comandos:
        // java MiPrograma 2> errores.txt  (redirige solo System.err)

        System.out.println("Ambos mensajes aparecen en consola,");
        System.out.println("pero System.err se puede separar en la terminal.");
    }
}

