import java.util.Scanner;

public class EntradaValidada {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);
        int numero = -1;

        while (numero <= 0) {
            System.out.print("Introduce un numero entero positivo: ");
            if (teclado.hasNextInt()) {
                numero = teclado.nextInt();
                if (numero <= 0) {
                    System.err.println("Error: el numero debe ser positivo.");
                }
            } else {
                System.err.println("Error: no has introducido un numero valido.");
                teclado.next();
            }
        }

        System.out.println("Numero valido: " + numero);
        teclado.close();
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Scanner;

public class CompararLectura {
    public static void main(String[] args) throws IOException {
        System.out.println("Este programa compara Scanner y BufferedReader.");
        System.out.println("Introduce 10 numeros enteros separados por espacios:");

        BufferedReader lector = new BufferedReader(new InputStreamReader(System.in));
        String linea = lector.readLine();
        String[] partes = linea.split(" ");

        long inicio1 = System.nanoTime();
        Scanner sc = new Scanner(linea);
        int[] numeros = new int[partes.length];
        for (int i = 0; i < partes.length; i++) {
            numeros[i] = sc.nextInt();
        }
        long fin1 = System.nanoTime();
        sc.close();

        System.out.println("Tiempo Scanner: " + (fin1 - inicio1) + " nanosegundos");
        System.out.println("Numeros leidos: " + numeros.length);

        for (int n : numeros) {
            System.out.print(n + " ");
        }
        System.out.println();
    }
}
